(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-116":{scenario:{company:"Mekong Breeze Foods",supervisor:{name:"Phan Thanh Tùng",role:{vi:"Trưởng bộ phận Kế toán Kho & Tài sản",en:"Inventory & Asset Accounting Lead"}},ref_code:"INV-2512",title:{vi:"Đếm đúng, ghi đúng, định giá thận trọng.",en:"Count right, record right, value prudently."},brief:{vi:"Kiểm kê kho thành phẩm ngày 31/12/2025 (biên bản INV-2512); công ty áp dụng Thông tư 200/2014/TT-BTC. Phát hiện thiếu 35 thùng sữa hạt trị giá 24,5 triệu đồng, chưa xác định nguyên nhân. Lô 1.200 hộp ngũ cốc có giá gốc 450.000 đồng/hộp; giá bán ước tính 420.000 đồng/hộp, chi phí bán ước tính 18.000 đồng/hộp (số liệu mô phỏng). Sửa tài khoản ghi nhận hàng thiếu và mức dự phòng giảm giá của lô ngũ cốc, rồi lập báo cáo có căn cứ.",en:"The finished goods count on 31 Dec 2025 (record INV-2512) is under review; the company applies Circular 200/2014/TT-BTC. 35 cartons of nut milk worth VND 24.5 million are missing with no known cause. A lot of 1,200 boxes of cereal costs VND 450,000 per box; the estimated selling price is VND 420,000 and estimated selling cost VND 18,000 per box (training data). Correct the shortage account and the write-down provision for the cereal lot, then report."},reference_title:{vi:"Biên bản kiểm kê & bảng đánh giá giá trị thuần · INV-2512",en:"Stock count record & net realizable value sheet · INV-2512"},fields:[{id:"SHORT_ACCT",label:{vi:"TK ghi nhận hàng thiếu chưa rõ nguyên nhân",en:"Account for unexplained shortage"},initial:"632",expected:"1381",choices:["632","1381","811"],reference:"Biên bản kiểm kê & quy chế xử lý",hint:{vi:"Khi chưa có quyết định xử lý của cấp có thẩm quyền, giá trị hàng thiếu phải được theo dõi chờ xử lý, chưa đưa vào chi phí.",en:"Until the authorized decision is made, the shortage value is held pending resolution, not expensed."}},{id:"NRV_PROV",label:{vi:"Dự phòng giảm giá lô ngũ cốc (VND)",en:"Write-down provision for cereal lot (VND)"},initial:"36000000",expected:"57600000",reference:"Bảng đánh giá giá trị thuần",ref_value:{vi:"1.200 hộp; giá gốc 450.000 đ/hộp; giá bán ước tính 420.000 đ/hộp; chi phí bán ước tính 18.000 đ/hộp",en:"1,200 boxes; cost VND 450,000 each; estimated price VND 420,000; estimated selling cost VND 18,000 each"},hint:{vi:"Giá trị thuần có thể thực hiện được không phải giá bán; phải trừ chi phí ước tính để bán được hàng.",en:"Net realizable value is not the selling price; deduct the estimated cost to make the sale."}}],sop32:{vi:"Giá trị thuần có thể thực hiện được = giá bán ước tính - chi phí ước tính để hoàn thành và bán; dự phòng = (giá gốc - giá trị thuần) x số lượng khi giá trị thuần thấp hơn giá gốc (VAS 02).",en:"Net realizable value = estimated selling price - estimated costs to complete and sell; provision = (cost - NRV) x quantity when NRV is below cost (VAS 02)."},context:{label:"BIÊN BẢN KIỂM KÊ NHÁP / INV-2512",metrics:[{label:{vi:"Hàng thiếu chưa rõ nguyên nhân",en:"Unexplained shortage"},value:"24,500,000 VND"},{label:{vi:"Số lượng lô ngũ cốc",en:"Cereal lot quantity"},value:"1,200"},{label:{vi:"Giá gốc mỗi hộp",en:"Cost per box"},value:"450,000 VND"}]},crisis:{vi:"Thủ kho nhắn: “Anh chị ghi giúp 35 thùng thiếu vào hao hụt luôn, đừng lập biên bản truy trách nhiệm. Tháng sau em nâng định mức hao hụt lên là bù được, trưởng kho cũng đồng ý rồi.”",en:"The storekeeper messages you: “Please book the 35 missing cartons as normal loss and skip the accountability record. Next month I will raise the loss allowance to cover it, the warehouse head already agreed.”"},options:{safe:{vi:"Ghi nhận hàng thiếu chờ xử lý, lập biên bản đầy đủ, báo kế toán trưởng và hội đồng kiểm kê để xác định nguyên nhân, trách nhiệm bồi thường; không sửa định mức để che giấu.",en:"Record the shortage as pending, complete the count record, report to the chief accountant and count committee to find cause and liability; never alter allowances to hide it."},shortcut:{vi:"Ghi thẳng vào giá vốn như hao hụt thông thường và bỏ qua biên bản truy trách nhiệm.",en:"Book it straight to cost of sales as normal loss and skip the accountability record."},wait:{vi:"Để nguyên chênh lệch trên sổ, chờ đợt kiểm kê sau xem hàng có xuất hiện lại không.",en:"Leave the difference on the books and wait for the next count to see if the goods reappear."}},questions:{vi:["Vì sao hàng thiếu chưa rõ nguyên nhân phải ghi vào TK 1381? Trình bày cách bạn tính lại dự phòng giảm giá của lô ngũ cốc.","Quy trình xử lý hàng thiếu sau kiểm kê gồm những bước nào và ai có thẩm quyền quyết định?"],en:["Why must an unexplained shortage go to account 1381? Show how you recalculated the cereal write-down.","What steps follow a stock count shortage, and who has the authority to decide?"]},hints:{vi:["Đặt biên bản kiểm kê nháp cạnh quy chế xử lý thừa thiếu và đánh dấu dòng chưa có quyết định xử lý.","Tính giá trị thuần của một hộp trước rồi mới nhân số lượng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi chênh lệch kiểm kê phải được lập biên bản, không điều chỉnh định mức để che giấu."],en:["Place the draft count record next to the shortage policy and flag lines without a decision.","Work out the NRV of one box before multiplying by quantity in SOP 3.2.","Re-read SOP 4.2: every count difference needs a record; never adjust allowances to hide it."]}},learning:{summary:{vi:"Kế toán tài sản cố định và hàng tồn kho quản lý toàn bộ vòng đời tài sản: xác định nguyên giá, mở thẻ và trích khấu hao, theo dõi điều chuyển, sửa chữa, thanh lý; đồng thời tính giá nhập xuất kho, tổ chức kiểm kê, xử lý thừa thiếu và lập dự phòng giảm giá hàng tồn kho. Giá trị tạo ra là tài sản trên sổ khớp với thực tế, được định giá thận trọng và có trách nhiệm rõ ràng. Nghề đòi hỏi tỉ mỉ, nắm chắc VAS 02, VAS 03, VAS 04 và quy định về khấu hao.",en:"A fixed asset and inventory accountant manages the full asset life cycle: determining cost, opening asset cards and depreciating, tracking transfers, repairs and disposals; and also costs stock movements, organizes counts, resolves differences and provides for inventory write-downs. The value is book assets that match reality, are prudently valued and have clear accountability. The role demands precision and solid command of VAS 02, VAS 03, VAS 04 and depreciation rules."},responsibilities:{vi:["Xác định nguyên giá, mở thẻ tài sản cố định và lập lịch khấu hao theo chính sách đã đăng ký.","Ghi nhận tăng, giảm, điều chuyển, sửa chữa lớn và thanh lý tài sản có đủ hồ sơ.","Tính giá xuất kho theo phương pháp đã chọn và đối chiếu thẻ kho với sổ kế toán.","Tổ chức kiểm kê định kỳ, lập biên bản và đề xuất xử lý chênh lệch thừa thiếu.","Đánh giá giá trị thuần có thể thực hiện được và trích lập dự phòng giảm giá hàng tồn kho."],en:["Determine cost, open asset cards and set depreciation schedules under the registered policy.","Record additions, disposals, transfers, major repairs and write-offs with full files.","Cost stock issues by the chosen method and reconcile stock cards with the books.","Run periodic counts, prepare records and propose how to resolve differences.","Assess net realizable value and provide for inventory write-downs."]},competencies:[{name:{vi:"Ghi nhận tài sản cố định",en:"Fixed asset recognition"},desc:{vi:"Phân biệt tài sản cố định với công cụ dụng cụ, tài sản hữu hình với vô hình, chi phí được vốn hóa.",en:"Separate fixed assets from tools, tangible from intangible, and capitalizable costs."}},{name:{vi:"Khấu hao",en:"Depreciation"},desc:{vi:"Chọn phương pháp và thời gian khấu hao phù hợp, trích theo ngày bắt đầu sử dụng.",en:"Choose suitable methods and useful lives and depreciate from the date of use."}},{name:{vi:"Tính giá hàng tồn kho",en:"Inventory costing"},desc:{vi:"Áp dụng nhất quán phương pháp đích danh, bình quân gia quyền hoặc nhập trước xuất trước.",en:"Apply specific identification, weighted average or FIFO consistently."}},{name:{vi:"Tổ chức kiểm kê",en:"Stock count control"},desc:{vi:"Lập kế hoạch kiểm kê, chốt chứng từ, kiểm đếm độc lập và xử lý chênh lệch có trách nhiệm.",en:"Plan counts, lock cut-off, count independently and resolve differences with accountability."}},{name:{vi:"Thận trọng & trung thực",en:"Prudence & honesty"},desc:{vi:"Không che giấu hàng thiếu, không trì hoãn dự phòng khi giá trị thuần giảm.",en:"Never hide shortages or delay write-downs when net realizable value falls."}}],knowledge:{vi:["VAS 02 Hàng tồn kho: giá gốc, giá trị thuần có thể thực hiện được, phương pháp tính giá xuất kho.","VAS 03 Tài sản cố định hữu hình và VAS 04 Tài sản cố định vô hình: điều kiện ghi nhận, nguyên giá.","Thông tư 45/2013/TT-BTC (sửa đổi, bổ sung): tài sản cố định có thời gian sử dụng trên 1 năm và nguyên giá từ 30 triệu đồng trở lên; khung thời gian và phương pháp khấu hao.","Thông tư 48/2019/TT-BTC về dự phòng giảm giá hàng tồn kho.","Thông tư 200/2014/TT-BTC: TK 1381, 3381 xử lý thừa thiếu, không còn áp dụng phương pháp nhập sau xuất trước (LIFO)."],en:["VAS 02 Inventories: cost, net realizable value and cost formulas for issues.","VAS 03 Tangible and VAS 04 Intangible fixed assets: recognition criteria and cost.","Circular 45/2013/TT-BTC (as amended): fixed assets last over 1 year and cost VND 30 million or more; useful life ranges and depreciation methods.","Circular 48/2019/TT-BTC on inventory write-down provisions.","Circular 200/2014/TT-BTC: accounts 1381 and 3381 for shortages and surpluses; LIFO is no longer allowed."]},tools:["Phần mềm ERP phân hệ tài sản & kho","Hệ thống quản lý kho (WMS)","Máy quét mã vạch / RFID","Microsoft Excel","Thẻ và sổ theo dõi tài sản cố định"],kpis:{vi:["Tỷ lệ chênh lệch giá trị kiểm kê so với sổ sách.","Tỷ lệ tài sản cố định được gắn mã và xác nhận hiện trạng hằng năm.","Số ngày hoàn tất xử lý chênh lệch sau kiểm kê.","Số điều chỉnh khấu hao hoặc dự phòng do kiểm toán đề xuất."],en:["Count value variance against book value.","Share of fixed assets tagged and physically verified each year.","Days to resolve count differences.","Depreciation or provision adjustments proposed by auditors."]},day:[{time:"08:00",vi:"Đối chiếu phiếu nhập xuất kho hôm trước với thẻ kho và hệ thống quản lý kho.",en:"Match yesterday's receipts and issues with stock cards and the WMS."},{time:"09:30",vi:"Lập hồ sơ tăng tài sản cho máy đóng gói mới: hóa đơn, biên bản nghiệm thu, chạy thử.",en:"Prepare the addition file for a new packing machine: invoice, acceptance and test-run records."},{time:"13:30",vi:"Chạy khấu hao tháng, rà soát tài sản đã khấu hao hết nhưng vẫn sử dụng.",en:"Run monthly depreciation and review fully depreciated assets still in use."},{time:"15:00",vi:"Kiểm kê chọn mẫu kho thành phẩm cùng thủ kho và kiểm soát nội bộ.",en:"Do a sample count of finished goods with the storekeeper and internal control."},{time:"16:30",vi:"Cập nhật bảng giá trị thuần cho hàng cận hạn và đề xuất dự phòng.",en:"Update the NRV sheet for near-expiry goods and propose provisions."}],mistakes:{vi:["Ghi thẳng hàng thiếu chưa rõ nguyên nhân vào giá vốn, bỏ qua bước xác định trách nhiệm.","Tính giá trị thuần bằng giá bán mà quên trừ chi phí bán hàng, làm thiếu dự phòng.","Ghi nhận tài sản dưới 30 triệu đồng thành tài sản cố định hoặc vốn hóa cả chi phí đào tạo, chạy thử không đạt."],en:["Expensing an unexplained shortage directly and skipping the accountability step.","Using selling price as NRV without deducting selling costs, under-providing.","Recording items under VND 30 million as fixed assets or capitalizing training and failed test costs."]},career:[{vi:"Nhân viên kế toán kho",en:"Inventory accounting clerk"},{vi:"Kế toán tài sản cố định & hàng tồn kho",en:"Fixed asset & inventory accountant"},{vi:"Trưởng nhóm kế toán tài sản & chuỗi cung ứng",en:"Asset & supply chain accounting lead"},{vi:"Kế toán tổng hợp / Kiểm soát viên tài chính",en:"General accountant / Financial controller"}],glossary:[{term:"Nguyên giá",vi:"Toàn bộ chi phí bỏ ra để có tài sản tính đến thời điểm đưa vào trạng thái sẵn sàng sử dụng.",en:"Historical cost: all costs to bring an asset to working condition for its intended use."},{term:"NRV",vi:"Giá trị thuần có thể thực hiện được: giá bán ước tính trừ chi phí hoàn thành và chi phí bán hàng ước tính.",en:"Net realizable value: estimated selling price less estimated costs to complete and sell."},{term:"Khấu hao đường thẳng",vi:"Phân bổ đều nguyên giá trừ giá trị thanh lý ước tính trong suốt thời gian sử dụng.",en:"Straight-line depreciation: spreading cost less residual value evenly over the useful life."},{term:"TK 1381",vi:"Tài sản thiếu chờ xử lý: giá trị tài sản thiếu khi kiểm kê chưa có quyết định xử lý.",en:"Assets missing pending resolution: shortages found at counts awaiting a decision."},{term:"Cut-off",vi:"Chốt chứng từ nhập xuất tại thời điểm kiểm kê để số liệu sổ và thực tế cùng một mốc.",en:"Locking receipt and issue documents at count time so book and physical figures share one point."}],quiz:[{q:{vi:"Máy nguyên giá 600 triệu đồng, khấu hao đường thẳng 5 năm, không có giá trị thanh lý, đưa vào sử dụng ngày 01/07. Khấu hao đến 31/12 cùng năm là bao nhiêu?",en:"A machine costs VND 600 million, straight-line over 5 years with no residual value, in use from 1 July. What is depreciation to 31 December of that year?"},options:{vi:["120 triệu đồng","60 triệu đồng","50 triệu đồng","100 triệu đồng"],en:["VND 120 million","VND 60 million","VND 50 million","VND 100 million"]},answer:1,explain:{vi:"Khấu hao năm 120 triệu đồng, mỗi tháng 10 triệu đồng; từ tháng 7 đến tháng 12 là 6 tháng nên bằng 60 triệu đồng.",en:"Annual depreciation is VND 120 million, VND 10 million a month; July to December is 6 months, so VND 60 million."}},{q:{vi:"Máy tính xách tay giá 26 triệu đồng, dùng 3 năm. Theo Thông tư 45/2013/TT-BTC, kế toán ghi nhận thế nào?",en:"A laptop costs VND 26 million and will be used for 3 years. Under Circular 45/2013/TT-BTC, how is it recorded?"},options:{vi:["Tài sản cố định hữu hình, khấu hao 3 năm","Chi phí toàn bộ trong tháng mua","Công cụ dụng cụ, phân bổ dần vào chi phí","Tài sản cố định vô hình"],en:["Tangible fixed asset depreciated over 3 years","Expensed fully in the month bought","Tools and supplies, allocated to expense over time","Intangible fixed asset"]},answer:2,explain:{vi:"Nguyên giá dưới 30 triệu đồng không đủ tiêu chuẩn tài sản cố định; dùng nhiều kỳ nên phân bổ dần như công cụ dụng cụ.",en:"Cost below VND 30 million fails the fixed asset test; used over several periods, it is allocated as a tool."}},{q:{vi:"Phương pháp tính giá xuất kho nào không còn được áp dụng theo Thông tư 200/2014/TT-BTC?",en:"Which inventory cost formula is no longer allowed under Circular 200/2014/TT-BTC?"},options:{vi:["Thực tế đích danh","Bình quân gia quyền","Nhập trước xuất trước (FIFO)","Nhập sau xuất trước (LIFO)"],en:["Specific identification","Weighted average","First in, first out (FIFO)","Last in, first out (LIFO)"]},answer:3,explain:{vi:"Thông tư 200/2014/TT-BTC đã bỏ phương pháp LIFO; doanh nghiệp chọn đích danh, bình quân gia quyền, FIFO hoặc giá bán lẻ phù hợp.",en:"Circular 200/2014/TT-BTC dropped LIFO; companies use specific identification, weighted average, FIFO or the retail method where suitable."}},{q:{vi:"Thủ kho đề nghị ghi hàng thiếu vào hao hụt và nâng định mức tháng sau để che giấu. Bạn làm gì?",en:"The storekeeper asks you to book a shortage as normal loss and raise next month's allowance to hide it. What do you do?"},options:{vi:["Từ chối, ghi nhận hàng thiếu chờ xử lý và báo kế toán trưởng, hội đồng kiểm kê","Đồng ý vì số tiền không lớn","Ghi một nửa vào hao hụt","Chờ kiểm kê năm sau"],en:["Refuse, record the shortage as pending and report to the chief accountant and count committee","Agree because the amount is small","Book half as normal loss","Wait for next year's count"]},answer:0,explain:{vi:"Che giấu hàng thiếu làm sai lệch sổ sách và có thể che giấu thất thoát; phải lập biên bản và xử lý theo thẩm quyền.",en:"Hiding shortages misstates the books and may conceal theft; record it and resolve it through the proper authority."}}],tools_en:["ERP fixed asset & inventory module","Warehouse management system (WMS)","Barcode / RFID scanners","Microsoft Excel","Fixed asset cards and registers"]}}})})(window.KKR);
